import { describe, expect, it, vi } from 'vitest';

// client.ts is regenerated by tooling. If a regeneration drops the relay
// fetch, users on networks that block the Supabase host lose auth and data
// with no other symptom — so pin the wiring here.
const { createClient, relaySpy } = vi.hoisted(() => ({
  createClient: vi.fn((..._args: unknown[]) => ({})),
  relaySpy: vi.fn(async (..._args: unknown[]) => new Response('[]')),
}));
vi.mock('@supabase/supabase-js', () => ({ createClient }));
vi.mock('../relayFetch', () => ({ supabaseRelayFetch: relaySpy }));

describe('Supabase client wiring', () => {
  it('sends every request through the relay fetch', async () => {
    await import('../client');
    expect(createClient).toHaveBeenCalledTimes(1);
    const options = createClient.mock.calls[0][2] as { global?: { fetch?: (u: string, i?: RequestInit) => Promise<Response> } };
    const key = createClient.mock.calls[0][1] as string;
    const fetchFn = options.global?.fetch;
    expect(typeof fetchFn).toBe('function');

    await fetchFn!('https://aigxuutjaqsywioxjefr.supabase.co/functions/v1/x', { method: 'POST', body: '{}' });
    expect(relaySpy).toHaveBeenLastCalledWith('https://aigxuutjaqsywioxjefr.supabase.co/functions/v1/x', { method: 'POST', body: '{}' });

    await fetchFn!('https://aigxuutjaqsywioxjefr.supabase.co/rest/v1/t?select=id', { headers: { apikey: key, Authorization: `Bearer ${key}` } });
    expect(String(relaySpy.mock.lastCall?.[0])).toContain('apikey=');
  });
});
